'use client';

// Vendored from MerchFlow Charts components/web/ShowRows.tsx (commit in lib/merch-flow-report/VENDORED.md).
// Generated by scripts/sync-merch-flow-report.mjs; edit the PATCHES there, not this file.

import { gms } from '@/lib/merch-flow-report/brand/tokens';
import { usd, compactUsd, shortDate } from '@/lib/merch-flow-report/format';
import type { Show } from '@/lib/merch-flow-report/report/types';
import { monthTotals, inferTourStart, flagShows } from '@/lib/merch-flow-report/report/derive';

/**
 * One row per show, grouped by month.
 *
 * Replaces the rotated-label column chart and the separate gross and per-head
 * pages: the value sits beside its own bar, so the table and the chart are the
 * same object rather than the same numbers printed twice.
 */

const MUTED_BAR = '#C9CCD1';

export function ShowRows({ shows }: { shows: Show[] }) {
  const flagged = flagShows(shows, inferTourStart(shows));
  const months = monthTotals(flagged, inferTourStart(shows));

  const maxGross = Math.max(...shows.map((s) => s.grossUsd), 1);
  const maxPerHead = Math.max(...shows.map((s) => s.perHeadUsd ?? 0), 1);
  const avgGross = shows.reduce((sum, s) => sum + s.grossUsd, 0) / (shows.length || 1);
  const avgPerHead =
    shows.reduce((sum, s) => sum + (s.perHeadUsd ?? 0), 0) / (shows.length || 1);

  return (
    <div>
      <p className="mb-4 max-w-[75ch] text-[13px] leading-relaxed" style={{ color: gms.slate }}>
        All {shows.length} shows in date order. The bar is gross; the right column is
        spend per head. Red is above the tour average, grey is below, and the dashed
        line marks the average.
      </p>

      {months.map((month) => (
        <section key={month.key} className="mb-5">
          <div
            className="flex items-baseline justify-between border-b pb-1.5"
            style={{ borderColor: gms.black }}
          >
            <h3 className="text-[12px] font-bold uppercase tracking-[0.12em] text-ink">
              {month.label}
            </h3>
            <span className="tnum text-[12px]" style={{ color: gms.slate }}>
              {month.shows.length} shows · {compactUsd(month.gross)}
            </span>
          </div>

          <ul>
            {month.shows.map((show) => {
              const above = show.grossUsd >= avgGross;
              const perHead = show.perHeadUsd ?? 0;
              return (
                <li
                  key={`${show.date}-${show.city}`}
                  className="flex items-center gap-2 border-b py-1.5 sm:gap-3"
                  style={{ borderColor: '#F0F0F0' }}
                >
                  <span
                    className="tnum w-12 shrink-0 text-[12px] sm:w-14"
                    style={{ color: gms.slate }}
                  >
                    {shortDate(show.date)}
                  </span>

                  <span className="w-24 shrink-0 truncate text-[12px] font-medium text-ink sm:w-36 sm:text-[13px]">
                    {show.cityDisplay ?? show.city}
                    {show.flag && (
                      <span className="ml-1" style={{ color: gms.red }} title="Flagged">
                        <span aria-hidden="true">◆</span>
                        <span className="sr-only">(flagged)</span>
                      </span>
                    )}
                  </span>

                  {/* Gross bar, with the average marked in place. */}
                  <span className="relative hidden h-3.5 flex-1 sm:block">
                    <span
                      className="absolute left-0 top-0 h-full rounded-r-sm"
                      style={{
                        width: `${(show.grossUsd / maxGross) * 100}%`,
                        background: above ? gms.red : MUTED_BAR,
                      }}
                    />
                    <span
                      className="absolute top-[-2px] h-[calc(100%+4px)] border-l border-dashed"
                      style={{ left: `${(avgGross / maxGross) * 100}%`, borderColor: gms.slate }}
                    />
                  </span>

                  <span className="tnum w-16 shrink-0 text-right text-[12px] font-semibold text-ink sm:w-20 sm:text-[13px]">
                    {compactUsd(show.grossUsd)}
                  </span>

                  <span className="relative hidden h-3.5 w-20 shrink-0 lg:block">
                    <span
                      className="absolute left-0 top-0 h-full rounded-r-sm"
                      style={{
                        width: `${(perHead / maxPerHead) * 100}%`,
                        background: perHead >= avgPerHead ? gms.black : MUTED_BAR,
                      }}
                    />
                  </span>

                  <span
                    className="tnum w-14 shrink-0 text-right text-[12px] sm:w-16"
                    style={{ color: gms.slate }}
                  >
                    {perHead ? usd(perHead, 2) : '—'}
                  </span>
                </li>
              );
            })}
          </ul>
        </section>
      ))}

      <ul
        className="flex flex-wrap gap-x-5 gap-y-2 pt-1 text-[12px]"
        style={{ color: gms.slate }}
      >
        {[
          ['Above average gross', gms.red],
          ['Below average gross', MUTED_BAR],
          ['Above average per head', gms.black],
        ].map(([label, color]) => (
          <li key={label} className="flex items-center gap-1.5">
            <span
              className="inline-block h-2.5 w-2.5 rounded-[2px]"
              style={{ background: color }}
            />
            {label}
          </li>
        ))}
        <li className="flex items-center gap-1.5">
          <span style={{ color: gms.red }}>◆</span>
          Flagged — outside the tour leg or per head looks wrong
        </li>
      </ul>
    </div>
  );
}
